  const companyId = ctx.param("companyId") ?? "";
  assertCompanyAccessCtx(ctx, companyId);
  if (ctx.actor?.type !== "board") {
    return Response.json({ error: "Board authentication required" }, { status: 403 });
  }
  if (!ctx.actor.userId) {
    return Response.json({ error: "Board user context required" }, { status: 403 });
  }

  const body = await ctx.json();
  const parsed = inboxDismissalSchema.parse(body);

